#!/bin/bash
# Multi-file 16-stream test = TBTransfer.app's real directory-push path:
#   ls -1A <dir> | xargs -P 16 -I{} rsync -aWL --inplace --no-compress --partial <dir>/{} <remote>/
# This is what actually moves the user's multi-shard model dirs. Reuses the
# payload already generated by throughput-bench.sh (no regeneration).
set -uo pipefail
KEY="$HOME/.ssh/tbtransfer_ed25519"
RSYNC=/opt/homebrew/bin/rsync
SSHOPTS="-i $KEY -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=6 -o BatchMode=yes -c aes128-gcm@openssh.com -o Compression=no -o ControlMaster=no"
SSHBASE=(-i "$KEY" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new -o ConnectTimeout=6 -o BatchMode=yes -c aes128-gcm@openssh.com -o Compression=no -o ControlMaster=no)
PAYLOAD="/tmp/tb_bench_payload.bin"
now(){ python3 -c 'import time;print(time.time())'; }
report(){ python3 - "$1" "$2" "$3" <<'PY'
import sys
name=sys.argv[1]; b=float(sys.argv[2]); s=float(sys.argv[3])
if s<=0:s=1e-9
print(f"  {name:34s} {b/1e9:6.2f} GB / {s:6.2f}s  =>  {b/s/1e9:5.2f} GB/s   {b*8/s/1e9:6.1f} Gbit/s")
PY
}

# build a chunk dir of N x 512MiB files from the cached payload
make_dir(){ local dir=$1 n=$2; rm -rf "$dir"; mkdir -p "$dir"
  for i in $(seq 1 "$n"); do
    dd if="$PAYLOAD" of="$dir/chunk_$i.bin" bs=1m count=512 skip=$(( (i-1)*512 )) 2>/dev/null
  done
}

start_daemon(){ local user=$1 ip=$2 port=$3
  ssh "${SSHBASE[@]}" "$user@$ip" "bash -s" >/tmp/tb_pardaemon.log 2>&1 <<EOF &
set -e
CONF=\$(mktemp /tmp/tb_bench_rsyncd.XXXXXX.conf)
cat > "\$CONF" <<'CONF_EOF'
use chroot = no
read only = no
hosts allow = 169.254.0.0/16
hosts deny = *
max connections = 32
lock file = /tmp/tb_bench_rsyncd.lock
log file = /tmp/tb_bench_rsyncd.log
pid file = /tmp/tb_bench_rsyncd.pid
[home]
    path = HOMEPLACEHOLDER
    read only = no
    list = no
CONF_EOF
sed -i.bak "s|HOMEPLACEHOLDER|\$HOME|" "\$CONF" && rm -f "\$CONF.bak"
exec $RSYNC --daemon --no-detach --port $port --config "\$CONF" --address $ip
EOF
  DPID=$!
  local i; for i in $(seq 1 40); do nc -z -G 1 "$ip" "$port" 2>/dev/null && return 0; sleep 0.2; done
  return 1
}

par_daemon_test(){ local label=$1 user=$2 ip=$3 port=$4 dir=$5
  ssh "${SSHBASE[@]}" "$user@$ip" 'mkdir -p ~/tb_bench_pardir' 2>/dev/null
  if ! start_daemon "$user" "$ip" "$port"; then echo "  $label par-daemon: daemon never bound"; kill "$DPID" 2>/dev/null; return; fi
  local sz t0 t1; sz=$(du -sk "$dir" | awk '{print $1*1024}')
  t0=$(now)
  ls -1A "$dir" | xargs -P 16 -I{} "$RSYNC" -aWL --inplace --no-compress --partial "$dir"/"{}" "rsync://$ip:$port/home/tb_bench_pardir/" 2>/tmp/tb_par.err
  t1=$(now)
  report "$label  16-stream rsync-daemon" "$sz" "$(python3 -c "print($t1-$t0)")"
  kill "$DPID" 2>/dev/null
  ssh "${SSHBASE[@]}" "$user@$ip" 'rm -rf ~/tb_bench_pardir /tmp/tb_bench_rsyncd.*' 2>/dev/null
}

par_ssh_test(){ local label=$1 user=$2 ip=$3 dir=$4
  ssh "${SSHBASE[@]}" "$user@$ip" 'mkdir -p ~/tb_bench_pardir' 2>/dev/null
  local sz t0 t1; sz=$(du -sk "$dir" | awk '{print $1*1024}')
  t0=$(now)
  ls -1A "$dir" | xargs -P 16 -I{} "$RSYNC" -aWL --inplace --no-compress --partial -e "ssh $SSHOPTS" "$dir"/"{}" "$user@$ip:~/tb_bench_pardir/" 2>/tmp/tb_par_ssh.err
  t1=$(now)
  report "$label  16-stream rsync over ssh" "$sz" "$(python3 -c "print($t1-$t0)")"
  ssh "${SSHBASE[@]}" "$user@$ip" 'rm -rf ~/tb_bench_pardir' 2>/dev/null
}

echo "=== 16-stream parallel (TBTransfer directory-push path) ==="
echo "==> building chunk dirs from cached payload…"
make_dir /tmp/tb_dir24 24   # 12 GiB for mbp2 (463 GiB free)
make_dir /tmp/tb_dir16 16   #  8 GiB for mbp1 (30 GiB free)

echo
echo "--- mbp2 (ray@169.254.10.220 via en4, 12 GiB / 24 files) ---"
par_daemon_test mbp2 ray 169.254.10.220 8731 /tmp/tb_dir24
par_ssh_test    mbp2 ray 169.254.10.220 /tmp/tb_dir24
echo
echo "--- mbp1 (rd@169.254.204.227 via en3, 8 GiB / 16 files) ---"
par_daemon_test mbp1 rd  169.254.204.227 8731 /tmp/tb_dir16
par_ssh_test    mbp1 rd  169.254.204.227 /tmp/tb_dir16

rm -rf /tmp/tb_dir24 /tmp/tb_dir16
echo
echo "==> done."
